/*
 * Tree files support
 *
 * An export configured with "treefiles = true" is not stored in a
 * single large file. Instead, the export is split into fixed-size
 * block files (TREEPAGESIZE bytes each) which are organised in a tree
 * of directories with at most TREEDIRSIZE entries per directory. The
 * tree is as shallow as possible for the size of the export; a given
 * offset in the export maps to exactly one block file, so reads and
 * writes always end up in the same place.
 *
 * Block files are created on demand when data is written to them, and
 * are deleted again when the corresponding block is trimmed.
 */

#include <fcntl.h>
#include <limits.h>
#include <inttypes.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>

#include "config.h"
#include "cliserv.h"
#include "treefiles.h"
#include "nbd-debug.h"

/**
 * Construct the path, relative to the root of the tree, of the block
 * file holding a given position.
 *
 * The path is written into name, which must have room for the path of
 * the subtree of the given size. The function recurses, adding one
 * path component per level of the tree; the leaf level adds the
 * FILEXXXX component, higher levels add TREEXXXX components.
 *
 * @param name buffer to write the path to; the result is appended to
 * what is already there (usually the root of the tree)
 * @param lenmax size of the buffer at name
 * @param size total size, in bytes, of the (sub)tree being described
 * @param pos byte offset into the export for which to construct the path
 * @param ppos scratch value used to communicate the index of the
 * current subtree between the recursive invocations; its initial
 * content is ignored
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	if (lenmax < 10)
		err("Char buffer overflow. This is likely a bug.");

	if (size < TREEDIRSIZE * TREEPAGESIZE) {
		/* we are done, add filename */
		snprintf(name, lenmax, "/FILE%04" PRIX64,
			 (uint64_t)((pos / TREEPAGESIZE) % TREEDIRSIZE));
		*ppos = pos / (TREEPAGESIZE * TREEDIRSIZE);
	} else {
		char buffer[10];
		construct_path(name + 9, lenmax - 9, size / TREEDIRSIZE, pos, ppos);
		snprintf(buffer, sizeof(buffer), "/TREE%04jX",
			 (intmax_t)(*ppos % TREEDIRSIZE));
		memcpy(name, buffer, 9); /* copy without trailing zero */
		*ppos /= TREEDIRSIZE;
	}
}

/**
 * Delete the block file holding a given position, if it exists.
 *
 * Used to free a block when it is trimmed; a subsequent read of the
 * block will return zeroes again.
 *
 * @param name root of the tree (i.e., the exportname)
 * @param size total size, in bytes, of the export
 * @param pos byte offset into the export of the block to delete
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char filename[PATH_MAX];
	off_t ppos;

	strncpy(filename, name, PATH_MAX - 1);
	filename[PATH_MAX - 1] = '\0';
	construct_path(filename + strlen(name), PATH_MAX - strlen(name) - 1, size, pos, &ppos);

	DEBUG("Deleting treefile: %s", filename);

	if (unlink(filename) == -1 && errno != ENOENT)
		DEBUG("Deleting failed: %s", strerror(errno));
}

/**
 * Create all directories in a path, if they do not exist yet.
 *
 * @param path absolute path; every component except the last one is
 * created as a directory. The string is modified in place while
 * working, but restored before we return.
 **/
void mkdir_path(char *path) {
	char *subpath = path + 1;

	while ((subpath = strchr(subpath, '/'))) {
		/* terminate the path at this position, so that we
		 * create all path components one by one */
		*subpath = '\0';
		if (mkdir(path, 0700) == -1) {
			if (errno != EEXIST)
				err("Path access error! %m");
		}
		*subpath = '/';
		subpath++;
	}
}

/**
 * Open the block file holding a given position of the export,
 * creating it (and any directories leading up to it) if necessary.
 *
 * @param name root of the tree (i.e., the exportname)
 * @param mode open mode; O_RDONLY if the export is read-only, O_RDWR
 * otherwise
 * @param size total size, in bytes, of the export
 * @param pos byte offset into the export of the block to open
 * @param mutex lock serialising creation of new block files
 * @return a file descriptor for the block file, positioned such that
 * the file is TREEPAGESIZE bytes in size
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char filename[PATH_MAX];
	off_t ppos;

	strncpy(filename, name, PATH_MAX - 1);
	filename[PATH_MAX - 1] = '\0';
	construct_path(filename + strlen(name), PATH_MAX - strlen(name) - 1, size, pos, &ppos);

	DEBUG("Accessing treefile %s (offset %llu of %llu)", filename, (unsigned long long)pos, (unsigned long long)size);

	pthread_mutex_lock(mutex);
	int handle = open(filename, mode, 0600);
	if (handle < 0 && errno == ENOENT) {
		if (mode & O_RDWR) {
			DEBUG("Creating new treepath");

			mkdir_path(filename);
			handle = open(filename, O_RDWR | O_CREAT, 0600);
			if (handle < 0) {
				err("Error opening tree block file %m");
			}
		} else {
			/* Reading a block which was never written must
			 * return zeroes; hand out an anonymous
			 * zero-filled file of the right size */
			DEBUG("Creating a dummy tempfile for reading");
			char tmpname[] = "dummy-XXXXXX";
			mode_t oldmode = umask(077);
			handle = mkstemp(tmpname);
			umask(oldmode);
			if (handle > 0) {
				unlink(tmpname); /* File will stick around whilst FD open */
			} else {
				err("Error opening tree block file %m");
			}
		}
		char *n = "\0";
		if (lseek(handle, TREEPAGESIZE - 1, SEEK_SET) < 0) {
			err("Could not create tree file!");
		}
		ssize_t c = write(handle, n, 1);
		if (c < 1) {
			err("Error setting tree block file size %m");
		}
	}
	pthread_mutex_unlock(mutex);
	return handle;
}

