Confirmed: request is magic(4) + type(4) + cookie(8) + from(8) + len(4). Now let's write the verification client. Place it in /tmp (outside the repo. Since the repo has its own tests, this is a throwaway verification tool).

Plan for the verification client (/tmp/treeclient.c):

Arguments: host port exportname, and run a fixed series of tests against a 4MiB export:

1. Negotiation (NBD_OPT_EXPORT_NAME), verify that the reported size is 4194304.
2. Read offset 0, length 8192 → expect all zeros (unwritten).
3. Write pattern A (0xAA repeating) at offset 4000, length 200 → straddles block boundary 4096.
4. Write pattern B at offset 1048576 (1MiB, block 256 → a different TREE directory? Let's compute: 1MiB/4MiB export: depth 1: TREE0000/FILE0256). Offset 3145728 (3MiB): FILE0768.
5. Read everything back and verify.
6. Read the surrounding area and confirm that only the written bytes changed (e.g., read the entire block 0 and verify that bytes 0..3999 are zero, 4000..4199 are pattern A, and 4200..4095 are zero).
7. FLUSH.
8. TRIM offset 4096*1 length 8192 (2 complete blocks: block 1 and block 2) — but note that pattern A occupies bytes 4000..4199 (part of block 0 and part of block 1). Trim [4096, 12288) completely covers blocks 1 and 2. After trim, read [4000,4200): bytes 4000..4095 are still pattern A (block 0 is retained), 4096..4199 are zero (block 1 is deleted).
9. Verify: partial trim [4096*4+100, 4096*5+100) → no blocks are completely covered... wait, min = ceil(from/4096)*4096 = 4096*5, max = floor((from+len)/4096)*4096 = 4096*5 → min==max, nothing deleted. Good — verify that the block files for block 4 and block 5 still exist and the data is intact.

Hmm, wait, let's actually make the trim test a bit simpler:
- Fully write blocks 1, 2, 3 with known data.
- TRIM [4096, 4096*3) → covers exactly blocks 1, 2 (from=4096: min=4096; from+len=12288: max=12288; blocks 4096 and 8192 are deleted).
- Verify that read-back is zeros and that the on-disk files are gone (the harness script checks the filesystem).

10. Additionally write something at offset 4190208 (last block, block 1023), then read it back — tests the last file of the tree.

The harness (shell script) then checks:
- Directory structure: ${tree}/TREE0000/FILE0000 etc. For a 4MiB export: depth — size=4194304, is size < 1024*4096=4194304? No, they're equal → recurse to size/1024=4096 → leaf level. So path = export/TREE%04X/FILE%04X with 1024 leaf files under TREE0000. After writing to offset 0.. (block 0), FILE0000 exists under TREE0000. Block 256 (1MiB) → FILE0100. Block 1023 → FILE03FF.
- After trim, FILE0001 and FILE0002 are gone.

Wait: block number = pos/4096. 1MiB = 1048576 = block 256 = 0x100 → FILE0100. 3MiB = block 768 = 0x300 → FILE0300. Last block 1023 = 0x3FF → FILE03FF.

Also verify that reading unwritten regions returns zeros (the client does this).

Now let's write the client. Byte-order helpers needed: htonll — implement manually (htobe64 is available via endian.h on Linux).

Client code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <errno.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>
#include <endian.h>

#define OPTS_MAGIC 0x49484156454F5054ULL
#define NBD_OPT_EXPORT_NAME 1
#define NBD_FLAG_C_FIXED_NEWSTYLE (1<<0)
#define NBD_FLAG_C_NO_ZEROES (1<<1)
#define NBD_REQUEST_MAGIC 0x25609513
#define NBD_REPLY_MAGIC 0x67446698
#define NBD_CMD_READ 0
#define NBD_CMD_WRITE 1
#define NBD_CMD_DISC 2
#define NBD_CMD_FLUSH 3
#define NBD_CMD_TRIM 4

static void rd(int f, void *buf, size_t len) { size_t off=0; while(off<len){ ssize_t r=read(f,(char*)buf+off,len-off); if(r<=0){fprintf(stderr,"short read: %s\n", r<0?strerror(errno):"EOF"); exit(1);} off+=r; } }
static void wr(int f, const void *buf, size_t len) { size_t off=0; while(off<len){ ssize_t r=write(f,(const char*)buf+off,len-off); if(r<=0){fprintf(stderr,"short write: %s\n", strerror(errno)); exit(1);} off+=r; } }

static uint64_t cookie=0;

static void send_req(int sock, uint32_t type, uint64_t from, uint32_t len) {
	uint32_t magic=htonl(NBD_REQUEST_MAGIC), t=htonl(type), l=htonl(len);
	uint64_t c=htobe64(++cookie), fr=htobe64(from);
	wr(sock,&magic,4); wr(sock,&t,4); wr(sock,&c,8); wr(sock,&fr,8); wr(sock,&l,4);
}

static void recv_reply(int sock, uint32_t *error) {
	uint32_t magic, err; uint64_t c;
	rd(sock,&magic,4); magic=ntohl(magic);
	if(magic!=NBD_REPLY_MAGIC){fprintf(stderr,"bad reply magic %x\n",magic);exit(1);}
	rd(sock,&err,4); rd(sock,&c,8);
	*error=ntohl(err);
}

static int do_read(int sock, uint64_t from, uint32_t len, unsigned char *buf) {
	send_req(sock, NBD_CMD_READ, from, len);
	uint32_t err; recv_reply(sock,&err);
	if(!err) rd(sock, buf, len);
	return err? -1:0;
}
static int do_write(int sock, uint64_t from, uint32_t len, const unsigned char *buf) {
	send_req(sock, NBD_CMD_WRITE, from, len);
	wr(sock, buf, len);
	uint32_t err; recv_reply(sock,&err);
	return err? -1:0;
}
static int do_simple(int sock, uint32_t type) {
	send_req(sock, type, 0, 0);
	uint32_t err; recv_reply(sock,&err);
	return err? -1:0;
}
static int do_trim(int sock, uint64_t from, uint32_t len) {
	send_req(sock, NBD_CMD_TRIM, from, len);
	uint32_t err; recv_reply(sock,&err);
	return err? -1:0;
}

static void check(int cond, const char *what) {
	if(!cond){ printf("FAIL: %s\n", what); exit(1);} 
	printf("ok: %s\n", what);
}

int main(int argc, char **argv) {
	if(argc<4){fprintf(stderr,"usage: %s host port exportname [expectsize]\n",argv[0]);return 2;}
	...connect...
	...negotiate...
	uint64_t expectsize = argc>4? strtoull(argv[4],NULL,0): 4194304;
	...
}
