/*
 * Minimal NBD client to functionally verify nbd-server treefiles:
 * block-granular layout, offset mapping, read/write consistency,
 * zero-fill of unwritten blocks and TRIM deleting block files.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <errno.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>
#include <endian.h>

#define OPTS_MAGIC 0x49484156454F5054ULL
#define NBD_OPT_EXPORT_NAME 1
#define NBD_FLAG_C_FIXED_NEWSTYLE (1 << 0)
#define NBD_REQUEST_MAGIC 0x25609513
#define NBD_REPLY_MAGIC 0x67446698
#define NBD_CMD_READ 0
#define NBD_CMD_WRITE 1
#define NBD_CMD_DISC 2
#define NBD_CMD_FLUSH 3
#define NBD_CMD_TRIM 4

static uint64_t cookie = 0;
static int failures = 0;

static void rd(int f, void *buf, size_t len) {
	size_t off = 0;
	while (off < len) {
		ssize_t r = read(f, (char *)buf + off, len - off);
		if (r <= 0) {
			fprintf(stderr, "FATAL: short read: %s\n", r < 0 ? strerror(errno) : "EOF");
			exit(1);
		}
		off += r;
	}
}

static void wr(int f, const void *buf, size_t len) {
	size_t off = 0;
	while (off < len) {
		ssize_t r = write(f, (const char *)buf + off, len - off);
		if (r <= 0) {
			fprintf(stderr, "FATAL: short write: %s\n", strerror(errno));
			exit(1);
		}
		off += r;
	}
}

static void check(int cond, const char *what) {
	if (!cond) {
		printf("FAIL: %s\n", what);
		failures++;
	} else {
		printf("ok: %s\n", what);
	}
}

static void send_req(int sock, uint32_t type, uint64_t from, uint32_t len) {
	uint32_t magic = htonl(NBD_REQUEST_MAGIC);
	uint32_t t = htonl(type);
	uint32_t l = htonl(len);
	uint64_t c = htobe64(++cookie);
	uint64_t fr = htobe64(from);
	wr(sock, &magic, 4);
	wr(sock, &t, 4);
	wr(sock, &c, 8);
	wr(sock, &fr, 8);
	wr(sock, &l, 4);
}

static uint32_t recv_reply(int sock) {
	uint32_t magic, err;
	uint64_t c;
	rd(sock, &magic, 4);
	if (ntohl(magic) != NBD_REPLY_MAGIC) {
		fprintf(stderr, "FATAL: bad reply magic %x\n", ntohl(magic));
		exit(1);
	}
	rd(sock, &err, 4);
	rd(sock, &c, 8);
	return ntohl(err);
}

static int do_read(int sock, uint64_t from, uint32_t len, unsigned char *buf) {
	send_req(sock, NBD_CMD_READ, from, len);
	uint32_t err = recv_reply(sock);
	if (!err)
		rd(sock, buf, len);
	return err ? -1 : 0;
}

static int do_write(int sock, uint64_t from, uint32_t len, const unsigned char *buf) {
	send_req(sock, NBD_CMD_WRITE, from, len);
	wr(sock, buf, len);
	return recv_reply(sock) ? -1 : 0;
}

static int do_simple(int sock, uint32_t type) {
	send_req(sock, type, 0, 0);
	return recv_reply(sock) ? -1 : 0;
}

static int do_trim(int sock, uint64_t from, uint32_t len) {
	send_req(sock, NBD_CMD_TRIM, from, len);
	return recv_reply(sock) ? -1 : 0;
}

static int all_of(const unsigned char *buf, size_t len, unsigned char v) {
	for (size_t i = 0; i < len; i++)
		if (buf[i] != v)
			return 0;
	return 1;
}

int main(int argc, char **argv) {
	if (argc < 4) {
		fprintf(stderr, "usage: %s host port exportname [expected-size]\n", argv[0]);
		return 2;
	}
	uint64_t expectsize = argc > 4 ? strtoull(argv[4], NULL, 0) : 4194304;
	int lastblock = argc > 5 ? 0 : 1; /* only test the final block when we know the size fits the default scenario */

	struct addrinfo hints;
	memset(&hints, 0, sizeof(hints));
	hints.ai_family = AF_UNSPEC;
	hints.ai_socktype = SOCK_STREAM;
	struct addrinfo *ai;
	if (getaddrinfo(argv[1], argv[2], &hints, &ai)) {
		perror("getaddrinfo");
		return 1;
	}
	int sock = socket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
	if (sock < 0 || connect(sock, ai->ai_addr, ai->ai_addrlen) < 0) {
		perror("connect");
		return 1;
	}

	/* newstyle negotiation, NBD_OPT_EXPORT_NAME */
	char buf8[8];
	rd(sock, buf8, 8);
	check(!memcmp(buf8, "NBDMAGIC", 8), "INIT_PASSWD");
	uint64_t m;
	rd(sock, &m, 8);
	check(be64toh(m) == OPTS_MAGIC, "option magic");
	uint16_t hflags;
	rd(sock, &hflags, 2);
	uint32_t cflags = htonl(NBD_FLAG_C_FIXED_NEWSTYLE);
	wr(sock, &cflags, 4);
	uint64_t om = htobe64(OPTS_MAGIC);
	wr(sock, &om, 8);
	uint32_t opt = htonl(NBD_OPT_EXPORT_NAME);
	wr(sock, &opt, 4);
	uint32_t nlen = htonl(strlen(argv[3]));
	wr(sock, &nlen, 4);
	wr(sock, argv[3], strlen(argv[3]));
	uint64_t size;
	rd(sock, &size, 8);
	size = be64toh(size);
	uint16_t tflags;
	rd(sock, &tflags, 2);
	char zeroes[124];
	rd(sock, zeroes, 124);
	check(size == expectsize, "export size as configured");
	if (size != expectsize) {
		fprintf(stderr, "size %llu != expected %llu, aborting\n",
			(unsigned long long)size, (unsigned long long)expectsize);
		return 1;
	}

	unsigned char *buf = malloc(65536);

	/* 1. unwritten blocks read back as zeroes */
	check(do_read(sock, 0, 8192, buf) == 0, "read of unwritten area succeeds");
	check(all_of(buf, 8192, 0), "unwritten blocks read as zeroes");

	/* 2. write a pattern crossing a block boundary */
	memset(buf, 0xAA, 200);
	check(do_write(sock, 4000, 200, buf) == 0, "write crossing block boundary");

	/* 3. writes at other spots of the tree */
	memset(buf, 0x5C, 4096);
	check(do_write(sock, 1048576, 4096, buf) == 0, "write block at 1MiB");
	memset(buf, 0x77, 100);
	check(do_write(sock, 4194200, 100, buf) == 0, "write near end of export");

	check(do_simple(sock, NBD_CMD_FLUSH) == 0, "flush");

	/* 4. read back and verify, including untouched surroundings */
	check(do_read(sock, 3900, 400, buf) == 0, "read back boundary write");
	check(all_of(buf, 100, 0) && all_of(buf + 100, 200, 0xAA) && all_of(buf + 300, 100, 0),
	      "boundary write landed correctly, surroundings untouched");
	check(do_read(sock, 1048576, 4096, buf) == 0, "read back 1MiB block");
	check(all_of(buf, 4096, 0x5C), "1MiB block content correct");
	check(do_read(sock, 4194200, 104, buf) == 0, "read back end-of-export write");
	check(all_of(buf, 100, 0x77) && all_of(buf + 100, 4, 0), "end-of-export content correct");

	/* 5. a larger write spanning many blocks */
	for (int i = 0; i < 65536; i++)
		buf[i] = (unsigned char)(i % 251);
	check(do_write(sock, 500000, 65536, buf) == 0, "64KiB write spanning many blocks");
	memset(buf, 0, 65536);
	check(do_read(sock, 500000, 65536, buf) == 0, "read back 64KiB write");
	int ok = 1;
	for (int i = 0; i < 65536; i++)
		if (buf[i] != (unsigned char)(i % 251)) {
			ok = 0;
			break;
		}
	check(ok, "64KiB content correct");

	/* 6. fill blocks 1, 2 and 3, then trim blocks 1 and 2 */
	memset(buf, 0x11, 4096);
	check(do_write(sock, 4096, 4096, buf) == 0, "write block 1");
	memset(buf, 0x22, 4096);
	check(do_write(sock, 8192, 4096, buf) == 0, "write block 2");
	memset(buf, 0x33, 4096);
	check(do_write(sock, 12288, 4096, buf) == 0, "write block 3");
	memset(buf, 0x44, 4096);
	check(do_write(sock, 16384, 4096, buf) == 0, "write block 4");

	check(do_trim(sock, 4096, 8192) == 0, "trim exactly blocks 1 and 2");
	check(do_read(sock, 4096, 8192, buf) == 0, "read trimmed area");
	check(all_of(buf, 8192, 0), "trimmed blocks read back as zeroes");
	check(do_read(sock, 4000, 96, buf) == 0, "read surviving part of block 0");
	check(all_of(buf, 96, 0xAA), "partial block before trimmed range survives");
	check(do_read(sock, 12288, 4096, buf) == 0, "read block after trimmed range");
	check(all_of(buf, 4096, 0x33), "block after trimmed range survives");

	/* 7. trim with unaligned start: only fully covered blocks go away */
	check(do_trim(sock, 12388, 8092) == 0, "trim with unaligned start");
	check(do_read(sock, 12288, 4096, buf) == 0, "read block 3 after partial trim");
	check(all_of(buf, 4096, 0x33), "partially covered block 3 survives");
	check(do_read(sock, 16384, 4096, buf) == 0, "read block 4 after partial trim");
	check(all_of(buf, 4096, 0), "fully covered block 4 was trimmed");

	check(do_simple(sock, NBD_CMD_FLUSH) == 0, "final flush");

	if (lastblock) {
		(void)0;
	}

	/* disconnect; no reply expected */
	send_req(sock, NBD_CMD_DISC, 0, 0);
	close(sock);

	free(buf);
	if (failures) {
		printf("%d FAILURES\n", failures);
		return 1;
	}
	printf("ALL OK\n");
	return 0;
}

