	size_t off = 0;
	while (off < len) {
		ssize_t r = read(f, (char *)buf + off, len - off);
		if (r <= 0) {
			fprintf(stderr, "short read: %s\n", r < 0 ? strerror(errno) : "EOF");
			exit(1);
		}
