	uint64_t c = htobe64(++cookie);
	uint64_t fr = htobe64(from);
	wr(sock, &magic, 4);
	wr(sock, &t, 4);
	wr(sock, &c, 8);
	wr(sock, &fr, 8);
	wr(sock, &l, 4);
}

static uint32_t recv_reply(int sock) {
	uint32_t magic, err;
	uint64_t c;
	rd(sock, &magic, 4);
	if (ntohl(magic) != NBD_REPLY_MAGIC) {
		fprintf(stderr, "bad reply magic\n");
		exit(1);
	}
	rd(sock, &err, 4);
